const crypto = require('crypto');

const body = $json.body ?? $json;
const rawJson = typeof body.json === 'string' ? body.json : JSON.stringify(body.json ?? {});

let event = {};
try {
  event = JSON.parse(rawJson);
} catch (e) {
  event = {};
}

const receivedKey = String(body.vpbx_api_key ?? '');
const receivedSign = String(body.sign ?? '');

const cfgKey = String($env.MANGO_API_KEY ?? '');
const cfgSalt = String($env.MANGO_API_SALT ?? '');
const routeTo = String($env.MANGO_ROUTE_TO_NUMBER ?? '');
const routeOnStatesRaw = String($env.MANGO_ROUTE_ON_STATES ?? 'Appeared');
const routeOnStates = routeOnStatesRaw.split(',').map((s) => s.trim()).filter(Boolean);

const computedSign = cfgSalt
  ? crypto.createHash('sha256').update(`${receivedKey}${rawJson}${cfgSalt}`).digest('hex')
  : '';

const keyOk = !cfgKey || cfgKey === receivedKey;
const signOk = !!cfgSalt && computedSign === receivedSign;

const callId = String(event.call_id ?? '');
const state = String(event.call_state ?? '');
const stateAllowed = routeOnStates.length === 0 || routeOnStates.includes(state);

const contextType = String(event.context_type ?? event.call_direction_type ?? '').trim();
const callDirection = String(event.call_direction ?? event.direction ?? '').toLowerCase();
const location = String(event.location ?? '').toLowerCase();
const hasLineNumber = !!String(event.to?.line_number ?? '').trim();
const fromExternalNumber = !!String(event.from?.number ?? '').trim();

const inboundByType = contextType === '1' || contextType.toLowerCase() === 'incoming' || contextType.toLowerCase() === 'inbound';
const inboundByDirection = ['incoming', 'inbound'].includes(callDirection);
const inboundByShape = location === 'abonent' && hasLineNumber && fromExternalNumber;
const isInbound = inboundByType || inboundByDirection || inboundByShape;

const sourceCommandId = String(event.command_id ?? '');
const isApiLoop = !!sourceCommandId;

const shouldRoute = keyOk && signOk && !!callId && !!routeTo && stateAllowed && isInbound && !isApiLoop;
const commandId = `cmd.n8n.route.${Date.now()}.${Math.random().toString(36).slice(2, 8)}`;

const debugReason = shouldRoute
  ? 'ok'
  : !cfgSalt
    ? 'MANGO_API_SALT is empty'
    : !signOk
      ? 'signature mismatch'
      : !keyOk
        ? 'vpbx_api_key mismatch'
        : !callId
          ? 'call_id empty'
          : !routeTo
            ? 'MANGO_ROUTE_TO_NUMBER is empty'
            : !stateAllowed
              ? `call_state ${state} not allowed`
              : !isInbound
                ? 'not inbound call event'
                : isApiLoop
                  ? 'skip api loop event (command_id present)'
                  : 'filtered';

return [{
  eventType: 'call',
  receivedKey,
  rawJson,
  event,
  callId,
  state,
  routeTo,
  commandId,
  keyOk,
  signOk,
  isInbound,
  sourceCommandId,
  shouldRoute,
  debugReason
}];

const crypto = require('crypto');

